INSERT INTO careers (title, summary, estimated_minutes, default_order, active) VALUES ('Registered Nurse', 'Registered nurses care for patients at the bedside, in clinics, and in schools. They check symptoms, give medicine, and explain care plans in plain language. Every shift mixes teamwork, quick thinking, and real human connection. If you like helping people on their hardest days, this career offers many directions.', 7, 1, TRUE);
