INSERT INTO career_pages (career_id, page_number, title) SELECT id, 3, 'Training and next steps' FROM careers WHERE title = 'Registered Nurse';
INSERT INTO content_blocks (page_id, block_order, block_type, body) SELECT p.id, 1, 'TEXT', 'A nurse starts a shift by learning how each patient did overnight. During the day they take vital signs, give treatments, and talk with doctors and families. Good nurses stay calm, notice small changes, and speak up for their patients.' FROM career_pages p JOIN careers c ON c.id = p.career_id WHERE c.title = 'Registered Nurse' AND p.page_number = 1;
INSERT INTO content_blocks (page_id, block_order, block_type, body) SELECT p.id, 2, 'TEXT', 'As you read on, ask yourself: would I enjoy this kind of day? What parts of being a registered nurse sound exciting, and what parts sound tiring?' FROM career_pages p JOIN careers c ON c.id = p.career_id WHERE c.title = 'Registered Nurse' AND p.page_number = 1;
INSERT INTO content_blocks (page_id, block_order, block_type, body) SELECT p.id, 1, 'TEXT', 'This short video comes from CareerOneStop, a career exploration service sponsored by the US Department of Labor. Watch for what workers say they like most about the job.' FROM career_pages p JOIN careers c ON c.id = p.career_id WHERE c.title = 'Registered Nurse' AND p.page_number = 2;
INSERT INTO content_blocks (page_id, block_order, block_type, url, label) SELECT p.id, 2, 'VIDEO_EMBED', 'https://www.youtube.com/embed/x4Y_2fpET0U', 'Registered Nurses Career Video' FROM career_pages p JOIN careers c ON c.id = p.career_id WHERE c.title = 'Registered Nurse' AND p.page_number = 2;
INSERT INTO content_blocks (page_id, block_order, block_type, body) SELECT p.id, 1, 'TEXT', 'Most nurses earn a two-year or four-year nursing degree and then pass a national licensing exam. Many keep learning to specialize in areas like children''s care, emergency care, or surgery.' FROM career_pages p JOIN careers c ON c.id = p.career_id WHERE c.title = 'Registered Nurse' AND p.page_number = 3;
