INSERT INTO careers (title, summary, estimated_minutes, default_order, active) VALUES ('Physical Therapist', 'Physical therapists help people move better and hurt less after an injury, surgery, or illness. They design exercise plans and guide patients through each step of recovery. Progress is measurable, so you can see your work change someone''s life. It is a good fit for people who like anatomy, coaching, and encouragement.', 7, 2, TRUE);
