INSERT INTO content_blocks (page_id, block_order, block_type, body) SELECT p.id, 1, 'TEXT', 'A therapist meets patients one at a time, tests their strength and movement, and builds a plan. They demonstrate exercises, adjust the plan, and cheer on small wins. Notes and insurance paperwork fill the gaps between sessions.' FROM career_pages p JOIN careers c ON c.id = p.career_id WHERE c.title = 'Physical Therapist' AND p.page_number = 1;
INSERT INTO content_blocks (page_id, block_order, block_type, body) SELECT p.id, 2, 'TEXT', 'As you read on, ask yourself: would I enjoy this kind of day? What parts of being a physical therapist sound exciting, and what parts sound tiring?' FROM career_pages p JOIN careers c ON c.id = p.career_id WHERE c.title = 'Physical Therapist' AND p.page_number = 1;
INSERT INTO content_blocks (page_id, block_order, block_type, body) SELECT p.id, 1, 'TEXT', 'This short video comes from CareerOneStop, a career exploration service sponsored by the US Department of Labor. Watch for what workers say they like most about the job.' FROM career_pages p JOIN careers c ON c.id = p.career_id WHERE c.title = 'Physical Therapist' AND p.page_number = 2;
INSERT INTO content_blocks (page_id, block_order, block_type, url, label) SELECT p.id, 2, 'VIDEO_EMBED', 'https://www.youtube.com/embed/FOF71Lb5SkA', 'Physical Therapists Career Video' FROM career_pages p JOIN careers c ON c.id = p.career_id WHERE c.title = 'Physical Therapist' AND p.page_number = 2;
INSERT INTO content_blocks (page_id, block_order, block_type, body) SELECT p.id, 1, 'TEXT', 'Physical therapists complete a bachelor''s degree and then a three-year doctoral program. They must also pass a licensing exam in the state where they work.' FROM career_pages p JOIN careers c ON c.id = p.career_id WHERE c.title = 'Physical Therapist' AND p.page_number = 3;
