INSERT INTO careers (title, summary, estimated_minutes, default_order, active) VALUES ('Paramedic', 'Paramedics are the first medical team on the scene of an emergency. They assess patients quickly, start treatment, and rush them to the hospital. The work is fast, unpredictable, and often lifesaving. You need a steady head and a real desire to help strangers.', 6, 3, TRUE);
INSERT INTO career_tags (career_id, tag_id) SELECT c.id, t.id FROM careers c, tags t, tag_categories g WHERE c.title = 'Paramedic' AND t.category_id = g.id AND g.name = 'Cluster' AND t.name = 'Health & Medicine';
