INSERT INTO content_blocks (page_id, block_order, block_type, body) SELECT p.id, 1, 'TEXT', 'A paramedic shift begins by checking the ambulance and its equipment. Calls can come at any moment, from car crashes to heart attacks to a child who is hard to breathe. Between calls, crews restock supplies and write careful reports.' FROM career_pages p JOIN careers c ON c.id = p.career_id WHERE c.title = 'Paramedic' AND p.page_number = 1;
INSERT INTO content_blocks (page_id, block_order, block_type, body) SELECT p.id, 2, 'TEXT', 'As you read on, ask yourself: would I enjoy this kind of day? What parts of being a paramedic sound exciting, and what parts sound tiring?' FROM career_pages p JOIN careers c ON c.id = p.career_id WHERE c.title = 'Paramedic' AND p.page_number = 1;
INSERT INTO content_blocks (page_id, block_order, block_type, body) SELECT p.id, 1, 'TEXT', 'This short video comes from CareerOneStop, a career exploration service sponsored by the US Department of Labor. Watch for what workers say they like most about the job.' FROM career_pages p JOIN careers c ON c.id = p.career_id WHERE c.title = 'Paramedic' AND p.page_number = 2;
INSERT INTO content_blocks (page_id, block_order, block_type, url, label) SELECT p.id, 2, 'VIDEO_EMBED', 'https://www.youtube.com/embed/C8zIHk9KKqI', 'Emergency Medical Technicians and Paramedics Career Video' FROM career_pages p JOIN careers c ON c.id = p.career_id WHERE c.title = 'Paramedic' AND p.page_number = 2;
INSERT INTO content_blocks (page_id, block_order, block_type, body) SELECT p.id, 1, 'TEXT', 'Paramedics finish an emergency medical technician course and then a paramedic program, often at a community college. They pass national and state exams to earn their license.' FROM career_pages p JOIN careers c ON c.id = p.career_id WHERE c.title = 'Paramedic' AND p.page_number = 3;
