INSERT INTO careers (title, summary, estimated_minutes, default_order, active) VALUES ('Software Developer', 'Software developers build the apps, games, and websites people use every day. They turn an idea into code, then test it and fix it until it works. Much of the job is solving puzzles with a team. If you enjoy making things from nothing, this is a very creative technical career.', 7, 4, TRUE);
