INSERT INTO content_blocks (page_id, block_order, block_type, body) SELECT p.id, 1, 'TEXT', 'A developer usually starts with a short team meeting about who is building what. Most of the day goes to writing code, reviewing teammates'' work, and tracking down bugs. Plenty of developers work from home part or all of the week.' FROM career_pages p JOIN careers c ON c.id = p.career_id WHERE c.title = 'Software Developer' AND p.page_number = 1;
