INSERT INTO careers (title, summary, estimated_minutes, default_order, active) VALUES ('Cybersecurity Analyst', 'Cybersecurity analysts protect computers, networks, and private data from hackers. They watch for suspicious activity and respond fast when something goes wrong. The work feels like being a detective and a guard at once. Demand for these skills keeps growing as more of life moves online.', 7, 5, TRUE);
