INSERT INTO content_blocks (page_id, block_order, block_type, body) SELECT p.id, 1, 'TEXT', 'An analyst reviews alerts, looks for unusual patterns, and decides which ones are real threats. They also test their own systems for weak spots and teach coworkers about safe habits. When an attack happens, the whole team works together to contain it.' FROM career_pages p JOIN careers c ON c.id = p.career_id WHERE c.title = 'Cybersecurity Analyst' AND p.page_number = 1;
