INSERT INTO content_blocks (page_id, block_order, block_type, body) SELECT p.id, 1, 'TEXT', 'Most analysts study computer science or information security and add certifications. Hands-on practice, such as capture-the-flag contests, helps a lot.' FROM career_pages p JOIN careers c ON c.id = p.career_id WHERE c.title = 'Cybersecurity Analyst' AND p.page_number = 3;
