INSERT INTO careers (title, summary, estimated_minutes, default_order, active) VALUES ('Data Scientist', 'Data scientists find patterns in large piles of information and turn them into answers. Companies use their work to predict trends, spot problems, and make smarter choices. They mix math, coding, and clear explanation. If you like asking why and then proving it with numbers, this career fits.', 7, 6, TRUE);
