INSERT INTO content_blocks (page_id, block_order, block_type, body) SELECT p.id, 1, 'TEXT', 'A data scientist spends much of the day cleaning data and writing code to explore it. They build models, check whether the results make sense, and then present findings to people who are not experts. Good communication matters as much as good math.' FROM career_pages p JOIN careers c ON c.id = p.career_id WHERE c.title = 'Data Scientist' AND p.page_number = 1;
