INSERT INTO careers (title, summary, estimated_minutes, default_order, active) VALUES ('Civil Engineer', 'Civil engineers design and oversee the roads, bridges, water systems, and buildings that communities rely on. They use math and science to make projects safe, affordable, and long-lasting. Their work is visible for decades. If you like seeing big things get built, you will enjoy this field.', 7, 7, TRUE);
