INSERT INTO content_blocks (page_id, block_order, block_type, body) SELECT p.id, 1, 'TEXT', 'A civil engineer splits time between the office and the job site. At a desk they run calculations and draw plans, and in the field they check that crews follow the design. They talk with city officials, builders, and neighbors along the way.' FROM career_pages p JOIN careers c ON c.id = p.career_id WHERE c.title = 'Civil Engineer' AND p.page_number = 1;
