INSERT INTO careers (title, summary, estimated_minutes, default_order, active) VALUES ('Robotics Engineer', 'Robotics engineers design, build, and test machines that sense their surroundings and act on their own. Their robots work in factories, hospitals, warehouses, and even outer space. The job blends mechanics, electronics, and programming. It rewards people who love tinkering and never mind a few failed prototypes.', 7, 8, TRUE);
