INSERT INTO content_blocks (page_id, block_order, block_type, body) SELECT p.id, 1, 'TEXT', 'A robotics engineer might spend the morning wiring sensors and the afternoon debugging code. Testing takes up a lot of time, because robots rarely work perfectly the first time. Team members from many specialties share what they learn.' FROM career_pages p JOIN careers c ON c.id = p.career_id WHERE c.title = 'Robotics Engineer' AND p.page_number = 1;
