INSERT INTO careers (title, summary, estimated_minutes, default_order, active) VALUES ('Mechanical Engineer', 'Mechanical engineers design the machines and moving parts behind everything from bike brakes to jet engines. They use physics and math to make products work well and last. They also test prototypes and improve them. If you wonder how things work, this is the career built on that question.', 7, 9, TRUE);
