INSERT INTO content_blocks (page_id, block_order, block_type, body) SELECT p.id, 1, 'TEXT', 'A mechanical engineer sketches designs on a computer and tests how parts handle heat, force, and wear. Some days are spent in a workshop or lab building prototypes. Meetings with designers and manufacturers keep everyone moving in the same direction.' FROM career_pages p JOIN careers c ON c.id = p.career_id WHERE c.title = 'Mechanical Engineer' AND p.page_number = 1;
