INSERT INTO careers (title, summary, estimated_minutes, default_order, active) VALUES ('Electrician', 'Electricians install and repair the wiring that powers homes, schools, and businesses. They read plans, run cable, and test circuits to keep people safe. You earn while you learn through an apprenticeship, and skilled electricians are always in demand. It suits people who like working with their hands and solving real problems.', 6, 10, TRUE);
