INSERT INTO content_blocks (page_id, block_order, block_type, body) SELECT p.id, 1, 'TEXT', 'An electrician arrives at a job site, reviews the plan, and gets to work with tools and meters. One day might mean wiring a new house, and the next means tracking down why a panel keeps tripping. Safety rules guide every step.' FROM career_pages p JOIN careers c ON c.id = p.career_id WHERE c.title = 'Electrician' AND p.page_number = 1;
