INSERT INTO careers (title, summary, estimated_minutes, default_order, active) VALUES ('Welder', 'Welders join metal parts using intense heat, building and repairing everything from bridges to race cars. The work takes a steady hand, sharp eyes, and respect for safety. Skilled welders can work in factories, shipyards, and construction sites around the world. It is a great pick for people who like to see solid results from their effort.', 6, 11, TRUE);
