INSERT INTO content_blocks (page_id, block_order, block_type, body) SELECT p.id, 1, 'TEXT', 'A welder reads a blueprint, prepares the metal, and chooses the right welding method. They wear protective gear and check each joint to make sure it is strong. Some jobs happen in a shop, while others happen high on a building frame or underwater.' FROM career_pages p JOIN careers c ON c.id = p.career_id WHERE c.title = 'Welder' AND p.page_number = 1;
