INSERT INTO careers (title, summary, estimated_minutes, default_order, active) VALUES ('Plumber', 'Plumbers install and fix the pipes that bring clean water in and carry waste away. Their work protects public health every day. They solve puzzles inside walls and under floors, often for customers who really need the help. Many plumbers eventually start their own businesses.', 6, 12, TRUE);
