INSERT INTO careers (title, summary, estimated_minutes, default_order, active) VALUES ('Graphic Designer', 'Graphic designers create the logos, posters, websites, and packaging that catch your eye. They combine art, color, and text to communicate an idea quickly. Many work freelance or from home. If you love visuals and enjoy solving a client''s problem, this career blends both.', 6, 13, TRUE);
