INSERT INTO careers (title, summary, estimated_minutes, default_order, active) VALUES ('Video Game Designer', 'Video game designers invent the rules, worlds, and challenges that make games fun to play. They work with artists, programmers, and writers to bring an idea to life. Testing and feedback shape every level. If you have ever wondered why a game feels great, this career digs into that question.', 7, 14, TRUE);
