INSERT INTO careers (title, summary, estimated_minutes, default_order, active) VALUES ('High School Teacher', 'High school teachers help teenagers learn a subject and grow into capable adults. They plan lessons, run discussions, and notice when a student needs extra help. Their influence is often remembered for life. If you love a subject and enjoy explaining it, teaching is a rewarding path.', 6, 19, TRUE);
