INSERT INTO careers (title, summary, estimated_minutes, default_order, active) VALUES ('Marine Biologist', 'Marine biologists study ocean life, from tiny plankton to giant whales. They collect samples, track animals, and learn how oceans are changing. Fieldwork can happen on boats, on beaches, and under the water. Strong science skills and a love of the sea are the starting point.', 7, 22, TRUE);
