INSERT INTO careers (title, summary, estimated_minutes, default_order, active) VALUES ('Environmental Scientist', 'Environmental scientists study air, water, and soil to find out how people affect nature. They help governments and companies clean up pollution and protect natural places. The job combines fieldwork, lab testing, and data analysis. It is a strong match for people who care about the planet and like evidence.', 7, 23, TRUE);
