INSERT INTO content_blocks (page_id, block_order, block_type, body) SELECT p.id, 1, 'TEXT', 'A lawyer spends much of the day reading, researching, and preparing documents. They meet clients, negotiate with the other side, and sometimes appear in court. Cases can take months or years, so patience matters.' FROM career_pages p JOIN careers c ON c.id = p.career_id WHERE c.title = 'Lawyer' AND p.page_number = 1;
INSERT INTO content_blocks (page_id, block_order, block_type, body) SELECT p.id, 2, 'TEXT', 'As you read on, ask yourself: would I enjoy this kind of day? What parts of being a lawyer sound exciting, and what parts sound tiring?' FROM career_pages p JOIN careers c ON c.id = p.career_id WHERE c.title = 'Lawyer' AND p.page_number = 1;
INSERT INTO content_blocks (page_id, block_order, block_type, body) SELECT p.id, 1, 'TEXT', 'This short video comes from CareerOneStop, a career exploration service sponsored by the US Department of Labor. Watch for what workers say they like most about the job.' FROM career_pages p JOIN careers c ON c.id = p.career_id WHERE c.title = 'Lawyer' AND p.page_number = 2;
INSERT INTO content_blocks (page_id, block_order, block_type, url, label) SELECT p.id, 2, 'VIDEO_EMBED', 'https://www.youtube.com/embed/aK2PVtgWLp8', 'Lawyer Career Video' FROM career_pages p JOIN careers c ON c.id = p.career_id WHERE c.title = 'Lawyer' AND p.page_number = 2;
INSERT INTO content_blocks (page_id, block_order, block_type, body) SELECT p.id, 1, 'TEXT', 'Lawyers earn a bachelor''s degree, attend three years of law school, and pass the bar exam. Debate and mock trial are good ways to try it out.' FROM career_pages p JOIN careers c ON c.id = p.career_id WHERE c.title = 'Lawyer' AND p.page_number = 3;
INSERT INTO content_blocks (page_id, block_order, block_type, url, label) SELECT p.id, 2, 'EXTERNAL_LINK', 'https://www.bls.gov/ooh/legal/lawyers.htm', 'Occupational Outlook Handbook: pay, outlook, and requirements' FROM career_pages p JOIN careers c ON c.id = p.career_id WHERE c.title = 'Lawyer' AND p.page_number = 3;
INSERT INTO careers (title, summary, estimated_minutes, default_order, active) VALUES ('Firefighter', 'Firefighters protect people and property by fighting fires and responding to emergencies. They also handle medical calls, rescues, and safety education. The crew lives and trains together, so trust is huge. It is a demanding job for people who want to help when it counts.', 6, 26, TRUE);
