INSERT INTO content_blocks (page_id, block_order, block_type, body) SELECT p.id, 1, 'TEXT', 'A shift includes equipment checks, training drills, and fitness work between calls. When the alarm sounds, the crew moves quickly with a clear plan. Many calls are medical emergencies rather than fires.' FROM career_pages p JOIN careers c ON c.id = p.career_id WHERE c.title = 'Firefighter' AND p.page_number = 1;
INSERT INTO content_blocks (page_id, block_order, block_type, body) SELECT p.id, 2, 'TEXT', 'As you read on, ask yourself: would I enjoy this kind of day? What parts of being a firefighter sound exciting, and what parts sound tiring?' FROM career_pages p JOIN careers c ON c.id = p.career_id WHERE c.title = 'Firefighter' AND p.page_number = 1;
