INSERT INTO content_blocks (page_id, block_order, block_type, url, label) SELECT p.id, 2, 'VIDEO_EMBED', 'https://www.youtube.com/embed/DNK5dYGn3Fg', 'Firefighters Career Video' FROM career_pages p JOIN careers c ON c.id = p.career_id WHERE c.title = 'Firefighter' AND p.page_number = 2;
INSERT INTO content_blocks (page_id, block_order, block_type, body) SELECT p.id, 1, 'TEXT', 'Firefighters usually complete a fire academy and an emergency medical technician course. Entry also requires passing physical and written tests.' FROM career_pages p JOIN careers c ON c.id = p.career_id WHERE c.title = 'Firefighter' AND p.page_number = 3;
