INSERT INTO careers (title, summary, estimated_minutes, default_order, active) VALUES ('Police Detective', 'Police detectives investigate serious crimes by gathering evidence and interviewing witnesses. They piece together clues to find out what happened and who is responsible. The work needs patience, honesty, and careful notes. It is a path for people who like solving real-world puzzles.', 6, 27, TRUE);
