INSERT INTO content_blocks (page_id, block_order, block_type, body) SELECT p.id, 1, 'TEXT', 'A detective visits crime scenes, talks with victims and witnesses, and follows leads. They write detailed reports and work with prosecutors to build cases. Hours can be long and unpredictable.' FROM career_pages p JOIN careers c ON c.id = p.career_id WHERE c.title = 'Police Detective' AND p.page_number = 1;
INSERT INTO content_blocks (page_id, block_order, block_type, body) SELECT p.id, 2, 'TEXT', 'As you read on, ask yourself: would I enjoy this kind of day? What parts of being a police detective sound exciting, and what parts sound tiring?' FROM career_pages p JOIN careers c ON c.id = p.career_id WHERE c.title = 'Police Detective' AND p.page_number = 1;
