INSERT INTO content_blocks (page_id, block_order, block_type, body) SELECT p.id, 1, 'TEXT', 'Detectives start as police officers, usually after a high school diploma or college coursework and an academy. They are promoted after proving themselves on patrol.' FROM career_pages p JOIN careers c ON c.id = p.career_id WHERE c.title = 'Police Detective' AND p.page_number = 3;
